code.cpp:
class Solution {
public:
    int minCut(string s) {
        int n = s.size();
        vector<int> cuts(n);
        for (int i = 0; i < n; i++) {
            cuts[i] = i;
        }

        for (int c = 0; c < n; c++) {
            // Odd length palindromes
            int l = c, r = c;
            while (l >= 0 && r < n && s[l] == s[r]) {
                if (l == 0) {
                    cuts[r] = 0;
                } else {
                    cuts[r] = min(cuts[r], cuts[l - 1] + 1);
                }
                l--;
                r++;
            }

            // Even length palindromes
            l = c;
            r = c + 1;
            while (l >= 0 && r < n && s[l] == s[r]) {
                if (l == 0) {
                    cuts[r] = 0;
                } else {
                    cuts[r] = min(cuts[r], cuts[l - 1] + 1);
                }
                l--;
                r++;
            }
        }

        return cuts[n - 1];
    }
};
